INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5162638, 748138, 30982, '<td valign="top">Colorful and bold, and excellent sense of just how big this thing is by including the gentleman!</td>', 'Colorful and bold, and excellent sense of just how big this thing is by including the gentleman!', '2009-01-01 12:02:21.000000', NULL, 1),
