(5174270, 751955, 25024, '<td valign="top">Nice sunburst and composition with lovely shadows and good tonal range</td>', 'Nice sunburst and composition with lovely shadows and good tonal range', '2009-01-06 06:50:18.000000', NULL, 1),
(5174272, 751706, 25024, '<td valign="top">Wow, that''s some beast - good advice! Great focus and DOF with amazing colours, well done</td>', 'Wow, that''s some beast - good advice! Great focus and DOF with amazing colours, well done', '2009-01-06 06:53:19.000000', NULL, 1),
