(5179169, 751662, 50695, '<td valign="top">I love the texture.</td>', 'I love the texture.', '2009-01-07 21:54:43.000000', NULL, 1),
(5179176, 751612, 50695, '<td valign="top">Wonderful portrait. Hints of Arbus, but more of a portrait than Arbus. In Arbus, the subjects seem more interested in the camera than anything else. Here, we have subjects interacting with each other.</td>', 'Wonderful portrait. Hints of Arbus, but more of a portrait than Arbus. In Arbus, the subjects seem more interested in the camera than anything else. Here, we have subjects interacting with each other.', '2009-01-07 21:57:22.000000', NULL, 1),
